<?php $cart=$_SESSION['cart']??[]; $cartTotal=0; ?><section class="panel"><div class="panel-head"><div><h2>Barang Pilihan</h2><p>Atur jumlah barang sebelum pengajuan</p></div><a href="?page=katalog">＋ Tambah Barang</a></div><?php if(!$cart): ?><div class="empty-state"><div>🛒</div><h3>Keranjang masih kosong</h3><p>Pilih barang yang kamu butuhkan dari katalog.</p><a class="btn primary" href="?page=katalog">Buka Katalog</a></div><?php else: ?><?php foreach($cart as $code=>$qty): foreach($store['barang'] as $b): if($b['kode']!==$code)continue; $cartTotal += $b['harga']*$qty; ?><div class="cart-row"><div class="product-mini">▦</div><div class="grow"><b><?= h($b['nama']) ?></b><small><?= h($b['kode']) ?> · <?= rupiah($b['harga']) ?>/unit/hari · <?= (int)$b['tersedia'] ?> tersedia</small></div><form method="post" class="quantity-form"><?= csrf_field() ?><input type="hidden" name="action" value="update_qty"><input type="hidden" name="code" value="<?= h($code) ?>"><input class="field qty-field" type="number" min="1" max="<?= (int)$b['tersedia'] ?>" name="qty" value="<?= (int)$qty ?>"><button class="icon-btn">✓</button></form><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="remove_cart"><input type="hidden" name="code" value="<?= h($code) ?>"><button class="icon-btn danger">×</button></form></div><?php endforeach; endforeach; ?><div class="cart-summary"><span>Subtotal estimasi harian</span><b><?= rupiah($cartTotal) ?></b></div><p class="muted">Total akhir mengikuti durasi sewa, biaya pengiriman, dan penawaran Admin.</p><div class="modal-actions"><a class="btn light" href="?page=katalog">Lanjut Belanja</a><a class="btn primary" href="?page=ajukan">Lanjut Pengajuan →</a></div><?php endif; ?></section>
